-- N+1 anti-pattern: 1 query for orders + N for items
SELECT * FROM orders WHERE user_id = $1;
-- then per order: SELECT * FROM items WHERE order_id = ?;

-- Fix: join or WHERE order_id = ANY($1)
SELECT o.*, i.*
FROM orders o
LEFT JOIN items i ON i.order_id = o.id
WHERE o.user_id = $1;
